  // Luton taxis a bit more often, supercars rare
  const FREQ = { fiesta: 14, corsa: 10, fiat500: 3, sportage: 3, focus: 10, golf: 10, polo: 7, qashqai: 7, astra: 6.5, yaris: 5.3, a3: 5.2, bmw1: 4.5, bmw3: 4.5, aold: 3, a45: 2.2, jazz: 3,
    zafira: 2.5, avensis: 1.5, tesla: 1.5, rangerover: 1.2, taxi: 3.5, taxi2: 3, prius: 2.2, prius2: 1.8, sclass: .6, rolls: .08, golfr: .15, v60: 1.2, xc40: 1.8, f812: .08, c63s: .5, c63: .4, x6: .5, x7: .4, bus: 1.2, dd: .8, coach: .3, gwagon: .5, urus: .15, gt3: .15, lambo: .1 };
  const PREMIUM = { bmw: 1, audi: 1, merc: 1, tesla: 1, rr: 1, g: 1, taxi: 1, toyota: 1, volvo: 1, rolls: 1, golfr: 1, fiat: 1, kia: 1, van: 1, cab: 1 }; // these lean on their own paint lists
  function paints(k) { if (SPORT[k]) return SPORT[k]; if (k === 'c63s') return SPORT.c63; const m = MAKE_OF[k]; if (!m) return null;
    const own = MAKE[m]; return PREMIUM[m] ? own : COMMON.concat(own); }
  // weighted list -> 60 slots so the game's random pick (ci % length) lands on each colour as often as it should
  function slots(list) { const tot = list.reduce((a, [, w]) => a + w, 0), out = []; list.forEach(([h, w]) => { const n = Math.max(1, Math.round(w / tot * 60)); for (let i = 0; i < n; i++) out.push(h); });
    for (let i = out.length - 1; i > 0; i--) { const j = (i * 7919 + 13) % (i + 1); [out[i], out[j]] = [out[j], out[i]]; } return out; }
  const RIMS = { silver: ['#d9dde3', '#8a9099'], gunmetal: ['#8a9099', '#4a4e56'], black: ['#3a3c42', '#16171b'], machined: ['#c9ccd3', '#2a2c32'], bronze: ['#b8965a', '#6e5428'], steel: ['#c9ccd3', '#9aa0a8'] };

  const MIX = (col, t, k) => { const n = parseInt(col.slice(1), 16), a = [n >> 16, n >> 8 & 255, n & 255]; return `rgb(${a.map(v => Math.round(v + (t - v) * k)).join(',')})`; };
  const LUM = col => { const n = parseInt(col.slice(1), 16); return ((n >> 16) * .3 + (n >> 8 & 255) * .59 + (n & 255) * .11) / 255; };
  // smooth curve through points (Catmull-Rom as beziers)
  function spline(c, P, move) { if (move) c.moveTo(P[0][0], P[0][1]); else c.lineTo(P[0][0], P[0][1]);
    // sharp turns (windscreen base, bumper corners) stay crisp corners; gentle ones are smoothed
    const crn = i => { const a = P[i - 1], b = P[i], d = P[i + 1]; if (!a || !d) return true; const u = Math.atan2(b[1] - a[1], b[0] - a[0]), v = Math.atan2(d[1] - b[1], d[0] - b[0]); let t = Math.abs(u - v); if (t > Math.PI) t = 2 * Math.PI - t; return t > .62; };
    for (let i = 0; i < P.length - 1; i++) { const p0 = P[i - 1] || P[i], p1 = P[i], p2 = P[i + 1], p3 = P[i + 2] || p2;
      const c1 = crn(i) ? [p1[0] + (p2[0] - p1[0]) / 3, p1[1] + (p2[1] - p1[1]) / 3] : [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
      const c2 = crn(i + 1) ? [p2[0] - (p2[0] - p1[0]) / 3, p2[1] - (p2[1] - p1[1]) / 3] : [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
      c.bezierCurveTo(c1[0], c1[1], c2[0], c2[1], p2[0], p2[1]); } }
  function topAt(s, f) { const t = s.top; let best = 0; for (let i = 1; i < t.length; i++) { const [a, b] = t[i - 1], [p, q] = t[i]; if ((f - a) * (f - p) <= 0 && p !== a) best = Math.max(best, b + (q - b) * (f - a) / (p - a)); } return best; }

